let chatScope=null,studio,ecom;
let lastViewKey='',lastPageKey='',db,view='home',tab='scenes',pid='braud-agency',sid='s01',vid=null,filter='all',referenceTab=false,busy=false,quote=null,previewStop=null;
let draftStorage;try{draftStorage=localStorage;}catch{}const drafts=createDraftStore(draftStorage);
const draftForms=new Set(['script-form','note-form','brief-form','scene-form','feedback-form']);
const memoryDrafts=new Map(),formBaselines=new WeakMap();
function formKey(f){return draftKey({id:f.id,sceneId:f.dataset.scene||'',assetId:f.dataset.asset||''},{pieceId:pid,sceneId:['note-form','scene-form','feedback-form'].includes(f.id)?scene()?.id:''});}
function formFields(f){return [...f.querySelectorAll('input:not([type=file]),textarea,select')].map((el,i)=>({key:el.id||el.name||String(i),value:el.type==='checkbox'?el.checked:el.value}));}
// Compare drafts with saved content, including drafts from currently hidden sections.
function savedDraftFields(key){
 const [,pieceId,formId,sceneId,assetId]=key.split(':');
 const p=db?.pieces.find(p=>p.id===pieceId),s=p?.scenes.find(s=>s.id===sceneId);
 if(!p)return null;
 const fields=values=>Object.entries(values).map(([key,value])=>({key,value:typeof value==='boolean'?value:String(value??'')}));
 if(formId==='script-form')return [{key:'_sourceScript',value:JSON.stringify(p.script)},...p.script.flatMap((l,i)=>[{key:'text-'+l.id,value:l.text||''},{key:'direction-'+l.id,value:l.direction||''},{key:String(3+i*4),value:String(l.start??'')},{key:String(4+i*4),value:String(l.end??'')}])];
 if(formId==='brief-form')return fields({title:p.title,brief:p.brief});
 if(formId==='scene-form'&&s)return fields({title:s.title,lineId:s.lineId,intent:s.intent,duration:s.duration,audioMode:s.audioMode,music:!!s.music});
 if(formId==='note-form'&&s)return fields({'note-input':''});
 if(formId==='feedback-form'&&s){const v=s.versions.find(v=>v.assetId===assetId);if(v)return fields({feedback:v.feedback||'',status:v.status==='rejected'?'rejected':'review'});}
 return null;
}
function pendingDrafts(){
 const prefix='braud-studio-draft-v1:'+pid+':',all=new Map(drafts.entries(prefix).map(({key,draft})=>[key,draft]));
 for(const [key,draft] of memoryDrafts)if(key.startsWith(prefix))all.set(key,draft);
 return [...all].filter(([key,draft])=>{if(draft.active===false)return false;const saved=savedDraftFields(key);if(!saved||hasDraftChanges(draft.fields,saved))return true;if(drafts.reconcile(key))memoryDrafts.delete(key);else memoryDrafts.set(key,{...draft,active:false});return false;});
}
function draftLabel(key){const [, ,formId,sceneId]=key.split(':'),label=({'script-form':'Guion','brief-form':'Idea','scene-form':'Dirección','note-form':'Indicación','feedback-form':'Revisión'})[formId]||'Borrador';const scene=piece()?.scenes.find(s=>s.id===sceneId);return label+(scene?' · '+scene.title:'');}
function setDraftStatus(){
 const pending=pendingDrafts(),statusEl=$('.saved-state');
 if(statusEl){statusEl.innerHTML=pending.length?`<button class="draft-status-action" data-act="review-drafts" title="Revisar cambios sin guardar">${icon('clock')}${pending.length===1?'Cambios sin guardar · '+esc(draftLabel(pending[0][0])):pending.length+' borradores sin guardar'}</button>`:icon('check')+'Guardado en este equipo';statusEl.classList.toggle('draft-pending',!!pending.length);}
 for(const f of document.querySelectorAll('form')){
  if(!draftForms.has(f.id))continue;
  let notice=f.querySelector('.draft-notice');const key=formKey(f),candidate=memoryDrafts.get(key)||drafts.read(key),saved=formBaselines.get(f)||savedDraftFields(key);
  const draft=candidate&&candidate.active!==false&&(!saved||hasDraftChanges(candidate.fields,saved))?candidate:null;
  if(draft&&!notice){notice=document.createElement('p');notice.className='draft-notice';notice.setAttribute('role','status');f.prepend(notice);}
  if(notice){notice.innerHTML=draft?`<span>${draft.persisted===false?'Borrador conservado solo en esta pestaña. Guarda antes de cerrarla.':'Borrador conservado en este navegador. Pulsa Guardar para aplicarlo.'}</span><button type="button" data-act="discard-draft">Descartar borrador</button>`:'';notice.hidden=!draft;}
 }
}
function restoreDrafts(){
 for(const f of document.querySelectorAll('form')){
  if(!draftForms.has(f.id))continue;
  if(!formBaselines.has(f))formBaselines.set(f,formFields(f));
  const k=formKey(f),draft=memoryDrafts.get(k)||drafts.read(k);
  if(!draft||draft.active===false||!hasDraftChanges(draft.fields,formBaselines.get(f)))continue;
  if(!memoryDrafts.has(k))memoryDrafts.set(k,{...draft,persisted:true});
  const fields=[...f.querySelectorAll('input:not([type=file]),textarea,select')];
  for(const [i,el] of fields.entries()){const field=draft.fields.find(x=>x.key===(el.id||el.name||String(i)));if(field){if(el.type==='checkbox')el.checked=!!field.value;else el.value=field.value;}}
 }
 setDraftStatus();
}
function clearFormDraft(f){if(!draftForms.has(f.id))return;const k=formKey(f);memoryDrafts.delete(k);drafts.clear(k);setDraftStatus();}
document.addEventListener('input',e=>{const f=e.target.closest('form');if(!f||!draftForms.has(f.id))return;const k=formKey(f),fields=formFields(f),persisted=drafts.write(k,fields);memoryDrafts.set(k,{fields,persisted});setDraftStatus();});
window.addEventListener('beforeunload',e=>{if([...memoryDrafts].some(([key,d])=>d.active!==false&&!d.persisted&&hasDraftChanges(d.fields,savedDraftFields(key)))){e.preventDefault();e.returnValue='';}});
const asset=id=>db.assets.find(a=>a.id===id), piece=()=>db.pieces.find(p=>p.id===pid)||db.pieces[0], scene=()=>piece()?.scenes.find(s=>s.id===sid)||piece()?.scenes[0];
const media=id=>`/media/${encodeURIComponent(id)}`;
const thumb=(a,alt='')=>a?.posterId?`<img src="${media(a.posterId)}" alt="${esc(alt)}">`:`<div class="empty-art">${icon('film')}</div>`;
const fmt=n=>Number(n||0).toLocaleString('es-ES',{maximumFractionDigits:2});
const date=d=>new Date(d).toLocaleDateString('es-ES',{day:'numeric',month:'short'});
const status=(s)=>({approved:'Aprobado',review:'Por revisar',rejected:'Descartado',completed:'Completado',ip_detected:'Rechazado por el proveedor',quoted:'Cotizado',in_progress:'Generando',submitting:'Enviando',unknown:'Por confirmar',download_pending:'Descarga pendiente',saving:'Guardando'})[s]||s;
const badge=(s,label)=>`<span class="badge ${s}">${s==='approved'?icon('check'):''}${esc(label||status(s))}</span>`;
