function homeLegacy(){return `<section class="home-hero"><div class="atmosphere" aria-hidden="true"><i></i><i></i></div><div class="eyebrow">TU ESPACIO DE PRODUCCIÓN CREATIVA</div><h1>Una idea.<br><span>Todo lo que puede ser.</span></h1><p>Dirige el concepto. Da forma a cada escena.<br>Construye la siguiente versión.</p><form id="new-idea" class="idea-box glass"><label class="sr-only" for="idea-input">Describe la pieza que quieres crear</label><textarea id="idea-input" name="idea" placeholder="¿Qué quieres crear hoy? Una idea, un guion, un nuevo enfoque…" required maxlength="3000"></textarea><div class="idea-bottom"><span>${icon('spark')}Empieza con lo que tienes</span><button class="send-button" type="submit" aria-label="Crear pieza desde esta idea">${icon('arrow')}</button></div></form><div class="hero-chips"><span>Guion propio</span><span>Personajes consistentes</span><span>Tu dirección, siempre</span></div></section><section class="projects-section"><div class="section-heading"><div><span class="eyebrow">EN TU ESTUDIO</span><h2>Donde lo dejamos.</h2></div>${button(icon('plus')+' Nueva pieza','new-piece','secondary')}</div><div class="project-grid">${db.pieces.map(p=>{const approved=p.scenes.filter(s=>s.selectedId).length;const cover=p.scenes.flatMap(s=>s.versions).find(v=>v.status==='approved')?.assetId;return `<button class="project-card glass" data-act="open-piece" data-id="${p.id}"><div class="project-cover">${cover?thumb(asset(cover),p.title):`<div class="empty-art">${icon('film')}</div>`}<span class="cover-label">${esc(p.brand||'PROYECTO')}</span><span class="cover-arrow">${icon('arrow')}</span>${cover&&p.id==='braud-agency'?'<div class="cover-caption">Serio.<br>Pero no tanto.</div>':''}</div><div class="project-info"><div><h3>${esc(p.title)}</h3><p>${p.scenes.length} escenas <span>·</span> ${approved} seleccionada${approved===1?'':'s'}</p></div>${badge(approved?'review':'draft',approved?'En producción':'Idea')}</div></button>`;}).join('')}<button class="new-project-card" data-act="new-piece"><span class="round-plus">${icon('plus')}</span><h3>Tu próxima pieza</h3><p>Un concepto nuevo.<br>El mismo espacio para crearlo.</p></button></div></section><section class="next-step glass"><div class="next-icon">${icon('audio')}</div><div><span class="eyebrow">EL SIGUIENTE PASO</span><h3>Primero la voz. Después, el ritmo.</h3><p>Define cómo debe sonar cada frase e incorpora la locución para colocar los clips.</p></div>${button('Trabajar el guion '+icon('arrow'),'open-script','text-btn')}</section>`;}
function workspaceLegacy(){const p=piece();if(!p)return empty('Todavía no hay piezas','Crea tu primera pieza en el estudio.');const s=scene();return `<div class="piece-heading"><div><button class="back-link" data-act="nav" data-view="home">${icon('back')} Todas las piezas</button><div class="title-row"><h1>${esc(p.title)}</h1><span class="format-chip">${esc(p.format||'9:16')}</span></div><p>${esc(p.brand)} <span> / </span> ${({off:"Voz en off",native:"Voz nativa",silent:"Sin habla",mixed:"Off y diálogo"})[p.audioMode]||"Dirección creativa"}</p></div><div class="heading-actions">${button(icon('more'),'edit-brief','icon-btn','aria-label="Editar título y briefing"')}${button(icon('download')+' Preparar entrega','export','secondary')}</div></div><div class="workspace-tabs" role="tablist" aria-label="Vistas de la pieza">${[['script',['off','mixed'].includes(p.audioMode)?'Guion y voz':'Idea y dirección','01'],['scenes','Escenas','02'],['assembly','Montaje','03']].map(([t,l,n])=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-act="tab" data-tab="${t}"><span>${n}</span>${l}</button>`).join('')}<span class="saved-state">${icon('check')} Guardado en este equipo</span></div>${tab==='script'?scriptView(p):tab==='assembly'?assembly(p):s?sceneView(p,s):`<div class="empty-panel">${empty('La primera escena empieza aquí','Añade una escena y dale una intención.')}${button(icon('plus')+' Añadir escena','add-scene','primary')}</div>`}`;}
function sceneView(p,s,{guided=false}={}){const v=s.versions.find(v=>v.assetId===vid)||s.versions.find(v=>v.assetId===s.selectedId)||s.versions.at(-1),a=v&&asset(v.assetId);return `<div class="scene-workspace" data-format="${esc(p.format)}"><aside class="scene-rail"><div class="rail-label">ESCENAS <span>${p.scenes.length}</span></div>${p.scenes.map((sc,i)=>{const cv=sc.versions.find(v=>v.assetId===sc.selectedId)||sc.versions.at(-1),ca=cv&&asset(cv.assetId);return `<button class="scene-tile ${sc.id===s.id?'selected':''}" data-act="scene" data-id="${sc.id}"><div class="scene-thumb">${ca?thumb(ca):`<span class="empty-number">${String(i+1).padStart(2,'0')}</span>`}<span class="scene-number">${String(i+1).padStart(2,'0')}</span>${sc.selectedId?`<span class="mini-approved">${icon('check')}</span>`:''}${ca?`<span class="duration">${fmt(ca.duration)} s</span>`:''}</div><strong>${esc(sc.title)}</strong><span>${sc.selectedId?'Seleccionada':sc.versions.length?'Pendiente de revisión':'Por desarrollar'}</span></button>`;}).join('')}${button(icon('plus')+' Añadir escena','add-scene','rail-add')}</aside><section class="scene-canvas"><div class="canvas-header"><span>${esc(s.title)}</span>${v?badge(v.status):badge('draft','Sin generar')}<span class="canvas-format">${esc(p.format)}</span><button class="icon-btn" data-act="expand-preview" aria-label="Ampliar vídeo">${icon('expand')}</button></div><div class="preview-stage">${a?`<video controls playsinline preload="metadata" ${a.posterId?`poster="${media(a.posterId)}"`:""} src="${media(a.id)}" aria-label="Vista previa de ${esc(s.title)}"></video>`:`<div class="stage-empty">${icon('film')}<h3>Una escena por imaginar.</h3><p>Define qué ocurre, elige las referencias<br>y prepara la primera generación.</p></div>`}</div><div class="version-bar"><div><span class="eyebrow">VERSIONES</span><strong>${s.versions.length?`${s.versions.length} exploracion${s.versions.length===1?'':'es'}`:'Sin exploraciones'}</strong></div>${s.versions.length?`<details class="version-picker"><summary aria-label="Elegir versión"><span>${esc(v?.label||'Elegir versión')}</span><svg class="icon picker-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m7 10 5 5 5-5"/></svg></summary><div class="glass-options version-options" role="group" aria-label="Versiones de la escena">${s.versions.map(x=>`<button class="glass-option ${v?.assetId===x.assetId?'is-selected':''}" data-act="version" data-id="${x.assetId}" aria-pressed="${v?.assetId===x.assetId}"><span class="option-tick">${icon('check')}</span><span class="option-name">${esc(x.label)}<small>${x.status==='approved'?'Aprobada':x.status==='rejected'?'Descartada':'Por revisar'}</small></span></button>`).join('')}</div></details>`:''}${button(icon('folder'),'reuse-clip','icon-btn','aria-label="Reutilizar un clip existente"')}${button(icon('upload'),'upload-clip','icon-btn','aria-label="Importar un clip"')}</div>${v?`<div class="review-row"><details class="review-feedback"><summary>Notas de revisión</summary><p>${esc(v.feedback||'¿Transmite lo que querías? Guarda la corrección junto a esta versión.')}</p></details><div class="review-actions"><button class="btn secondary" data-ecom="comment-selection">Comentar con el agente</button>${button(v.status==='approved'?icon('check')+' Seleccionado':icon('check')+' Aprobar y usar','approve',v.status==='approved'?'approved-button':'primary',`data-id="${v.assetId}"`)}</div></div>`:''}</section><aside class="direction-panel glass"><div class="panel-heading"><h2>Dirección</h2>${button(icon('settings'),'edit-scene','icon-btn','aria-label="Editar dirección de escena"')}</div>${s.lineId?`<span class="eyebrow">ESTE MOMENTO DEL GUION</span><blockquote>${esc(p.script.find(l=>l.id===s.lineId)?.text||'')}</blockquote><div class="panel-divider"></div>`:''}<div class="label-row"><span class="eyebrow">LO QUE QUEREMOS VER</span><button data-act="edit-scene">Editar</button></div><p class="intent">${esc(s.intent||'La dirección de esta escena está por definir.')}</p><div class="audio-pills"><span>${icon(s.audioMode==='off'?'audio':'film')}${({off:'Voz en off',native:'Voz nativa',silent:'Sin voz',mixed:'Off + diálogo'})[s.audioMode]}</span><span>${s.music?'Con música':'Sin música'}</span><span>${fmt(s.duration)} s</span></div><div class="scene-note"><span>${icon('audio')}</span><p>${['off','mixed'].includes(s.audioMode)?p.audioId?'Locución disponible. Puedes encajar esta escena en Montaje.':'Locución pendiente para esta escena.':'Esta escena no necesita locución separada. El ritmo lo marca la acción.'}</p></div><div class="panel-divider"></div><div class="label-row"><span class="eyebrow">REFERENCIAS · USO EXPLÍCITO</span><button data-act="edit-refs">Editar</button></div><div class="ref-stack">${s.refs.map(r=>`<div class="ref-item"><img src="${media(r.assetId)}" alt="${esc(asset(r.assetId)?.name)}"><div><strong>${esc(asset(r.assetId)?.name)}</strong><span>${({identity:'Identidad y vestuario',product:'Producto',palette:'Color y luz',setting:'Decorado'})[r.role]}</span></div>${r.confirmed?icon('check'):icon('clock')}</div>`).join('')||'<p class="muted">Sin referencias. Elige qué conservar antes de generar.</p>'}</div><button class="btn primary full" data-ecom="generate-agent">${icon("audio")} Preparar esta escena</button><button class="text-btn manual-generation" data-act="generate">Ver instrucciones y consultar coste</button><p class="micro">El agente concreta la escena contigo. El coste se autoriza antes de generar.</p><div class="panel-divider"></div>${guided?'<details class="guide-details"><summary>Indicaciones guardadas</summary>':''}<div class="label-row"><span class="eyebrow">INDICACIONES</span><span class="count">${p.notes.filter(n=>!n.sceneId||n.sceneId===s.id).length}</span></div><div class="notes-list">${p.notes.filter(n=>!n.sceneId||n.sceneId===s.id).slice(-3).map(n=>`<div class="note"><span>${esc(n.kind==='editing'?'Para edición':n.kind==='generation'?'Para generar':'Anotación')} · ${esc(n.status==='done'?'Hecho':n.status==='dismissed'?'Descartado':'Pendiente')} · ${date(n.at)}</span><p>${esc(n.text)}</p></div>`).join('')}</div><form id="note-form"><label class="sr-only" for="note-input">Nueva indicación para esta escena</label><textarea id="note-input" name="note" placeholder="Por ejemplo: una mirada más incómoda, sin cambiar el personaje…" required></textarea><button type="submit" class="note-save">Guardar indicación ${icon('arrow')}</button></form><p class="micro">Se conserva tal como la escribes. No genera contenido automáticamente.</p>${guided?'</details>':''}</aside></div>`;}
function scriptView(p){const off=['off','mixed'].includes(p.audioMode);return `<div class="script-layout ${off?'':'without-off'}"><section class="script-paper glass"><div class="section-heading"><div><span class="eyebrow">${off?'GUION Y DIRECCIÓN VOCAL':'IDEA Y DIRECCIÓN'}</span><h2>${off?'Lo que dices. Cómo lo dices.':'Lo que queremos contar.'}</h2></div>${button(icon('plus')+' Frase','add-line','secondary')}</div>${!off?`<p class="muted">${p.audioMode==='native'?'Las voces forman parte de las escenas. Define los diálogos y su interpretación con el agente.':'La pieza se cuenta con imágenes, acción y sonido. El texto es opcional.'}</p><div class="piece-brief"><p>${esc(p.brief||'La idea se irá concretando en la conversación.')}</p>${button('Editar idea','edit-brief','text-btn')}</div>`:'<p class="muted">Texto e interpretación se conservan por separado. Puedes trabajarlos hablando con el agente.</p>'}<form id="script-form"><input type="hidden" name="_sourceScript" value="${esc(JSON.stringify(p.script))}">${p.script.map((l,i)=>`<div class="script-line" data-line="${l.id}"><span class="line-number">${String(i+1).padStart(2,'0')}</span><div><label class="sr-only" for="text-${l.id}">Frase ${i+1}</label><textarea id="text-${l.id}" class="line-text" data-field="text">${esc(l.text)}</textarea><label class="direction-label" for="direction-${l.id}">${icon('audio')} Intención e interpretación</label><textarea id="direction-${l.id}" data-field="direction" class="line-direction" placeholder="Cómo debe sentirse…">${esc(l.direction)}</textarea>${off?`<details><summary>Tiempos de la locución</summary><div class="two-fields"><label>Empieza en la locución (s)<input data-field="start" type="number" min="0" step="0.01" value="${l.start??''}"></label><label>Termina en la locución (s)<input data-field="end" type="number" min="0" step="0.01" value="${l.end??''}"></label></div></details>`:`<input data-field="start" type="hidden" value="${l.start??''}"><input data-field="end" type="hidden" value="${l.end??''}">`}</div></div>`).join('')}${p.script.length?`<div class="sticky-save"><span>También puedes editarlo aquí.</span><button class="btn primary" type="submit">Guardar texto ${icon('check')}</button></div>`:''}</form></section>${off?`<aside class="voice-panel glass"><div class="voice-symbol">${icon('audio')}</div><span class="eyebrow">EL RITMO DEL MONTAJE</span><h2>Una voz.<br>Toda la intención.</h2><p>Preparamos la locución antes de colocar los clips.</p>${p.audioId?`<div class="audio-file"><strong>${esc(asset(p.audioId)?.name)}</strong><audio controls src="${media(p.audioId)}"></audio></div>`:'<div class="waiting-card">'+icon('clock')+'<span>Locución pendiente</span></div>'}${button(icon('upload')+' Importar locución','upload-audio','primary full')}<p class="micro">ElevenLabs: conexión directa pendiente. Puedes importar el audio.</p></aside>`:''}</div>`;}

function assembly(p){const offAudioId=['off','mixed'].includes(p.audioMode)?p.audioId:null;const clips=p.scenes.filter(s=>s.versions.length).map(s=>({s,a:asset(s.timeline?.assetId||s.selectedId||s.versions.at(-1).assetId)}));const total=Math.max(asset(offAudioId)?.duration||0,...clips.map(({s,a})=>(s.timeline?.start||0)+(s.timeline?.out??a.duration)-(s.timeline?.in||0)),1);return `<div class="assembly-layout"><section class="assembly-main glass"><div class="section-heading"><div><span class="eyebrow">MONTAJE PROVISIONAL</span><h2>Empieza a tomar forma.</h2></div>${badge('review',offAudioId?'Con locución':['off','mixed'].includes(p.audioMode)?'Locución pendiente':p.audioMode==='native'?'Audio nativo':'Sin habla')}</div><div class="assembly-screen"><video id="assembly-video" playsinline></video><div id="assembly-empty">Sin clip en este tramo</div></div><div class="transport">${button(icon('play')+' Reproducir','play-assembly','primary')}<span id="assembly-time">0:00 / ${fmt(total)} s</span><input id="assembly-seek" type="range" min="0" max="${total}" step="0.01" value="0" aria-label="Posición del montaje"><span>${esc(piece().format)}</span></div>${offAudioId?`<audio id="master-audio" src="${media(offAudioId)}"></audio>`:''}${['off','mixed'].includes(p.audioMode)?`<div class="track audio-track"><span>${icon('audio')} VOZ EN OFF</span><div>${offAudioId?`<strong>${esc(asset(offAudioId)?.name)}</strong><small>${fmt(asset(offAudioId)?.duration)} s</small>`:`<button data-act="upload-audio">${icon('plus')} Incorpora la locución para fijar los tiempos</button>`}</div></div>`:''}<div class="track"><span>${icon('film')} VISUALES</span><div class="visual-track">${clips.map(({s,a})=>`<button style="left:${100*(s.timeline?.start||0)/total}%;width:${100*((s.timeline?.out??a.duration)-(s.timeline?.in||0))/total}%" data-act="timeline-edit" data-id="${s.id}">${thumb(a)}<span>${esc(s.title)}</span></button>`).join('')}</div></div><p class="micro">Los clips sin aprobar pueden verse aquí como pruebas. La entrega incluye únicamente las versiones aprobadas y seleccionadas.</p></section><aside class="assembly-list glass"><span class="eyebrow">ORDEN Y DURACIÓN</span><h2>Cada plano, en su sitio.</h2>${clips.map(({s,a},i)=>`<button class="assembly-row" data-act="timeline-edit" data-id="${s.id}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(s.title)}</strong><small>${fmt(s.timeline?.start||0)} s → ${fmt((s.timeline?.start||0)+(s.timeline?.out??a.duration)-(s.timeline?.in||0))} s</small></div>${s.selectedId?icon('check'):icon('clock')}</button>`).join('')}<div class="waiting-card">${icon('film')}<span>${p.scenes.filter(s=>!s.versions.length).length} escenas sin visual</span></div><p class="muted">El editor especializado se conectará después. Ya puedes preparar materiales, tiempos y dirección.</p>${button(icon('download')+' Preparar entrega','export','secondary full')}</aside></div>`;}
function library(){const refs=ecom.dev&&referenceTab;const items=db.assets.filter(a=>a.clientId===studio.client().id&&a.category!=='still'&&a.category!=='inspiration'&&(filter==='all'||filter==='approved'&&a.approved||filter===a.kind));return `<div class="page-heading"><div><span class="eyebrow">UN LUGAR PARA LO QUE CONSERVAS</span><h1>Biblioteca.</h1><p>Personajes, materiales y referencias. Cada recurso con su contexto.</p></div>${button(icon('plus')+(refs?' Guardar referencia':' Importar archivo'),refs?'add-reference':'ecom-upload-resource','primary')}</div><div class="library-controls"><div class="segmented"><button data-act="library-tab" data-ref="false" class="${!refs?'active':''}">Recursos</button><button ${ecom.dev?"":"hidden"} data-act="library-tab" data-ref="true" class="${refs?'active':''}">Referencias de diseño <span>${(db.references||[]).length}</span></button></div>${!refs?`<div class="filter-pills">${[['all','Todo'],['approved','Aprobados'],['image','Imágenes'],['video','Vídeos'],['audio','Audio']].map(([v,l])=>`<button class="${filter===v?'active':''}" data-act="filter" data-filter="${v}">${l}</button>`).join('')}</div>`:''}</div>${refs?`<button class="btn secondary" data-act="design-study">Ver las 69 pruebas del laboratorio visual ${icon('arrow')}</button><div class="reference-intro glass"><span>${icon('link')}</span><p>Ideas y conceptos aportados por Jordi. Se conservan los originales y los enlaces; ninguna referencia fija por sí sola el branding.</p></div><div class="reference-grid">${(db.references||[]).map(r=>`<article class="reference-card glass">${r.assetId?`<button class="ref-art" data-act="asset-detail" data-id="${r.assetId}"><img loading="lazy" src="${media(r.assetId)}" alt="${esc(r.title)}"></button>`:`<div class="ref-link-art">${icon('link')}<span>${esc(r.title)}</span></div>`}<div><span class="eyebrow">EXPLORACIÓN · ${esc(r.createdAt?.slice(0,10))}</span><h3>${esc(r.title)}</h3><p>${esc(r.note)}</p>${r.url?`<a class="text-btn" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Ver referencia ${icon('arrow')}</a>`:''}</div></article>`).join('')}</div>`:`<div class="asset-grid">${items.map(a=>`<button class="asset-card glass" data-act="asset-detail" data-id="${a.id}"><div class="asset-image">${a.kind==='image'?`<img loading="lazy" src="${media(a.id)}" alt="${esc(a.name)}">`:a.kind==='video'?`${thumb(a)}${icon('play','video-overlay')}`:icon('audio')}${a.approved?'<span class="mini-approved">'+icon('check')+'</span>':''}</div><div class="asset-caption"><strong>${esc(a.name)}</strong><span>${esc(a.model||'Archivo propio')}${a.duration?' · '+fmt(a.duration)+' s':''}</span></div></button>`).join('')||empty('Todavía no hay recursos de este tipo','Importa un archivo para incorporarlo a la biblioteca.')}</div>`}`;}
function activity(){const scoped=db.pieces.filter(p=>p.clientId===ecom.brandId),ids=new Set(scoped.map(p=>p.id));const tasks=db.jobs.filter(j=>j.status!=='quoted'&&ids.has(j.pieceId));return `<div class="page-heading"><div><span class="eyebrow">LA PRODUCCIÓN, CON CONTEXTO</span><h1>Todo queda aquí.</h1><p>Generaciones, revisiones y decisiones. También las pruebas que no salieron.</p></div>${button(icon('clock')+' Recuperar estados','reconcile','secondary')}</div><div class="activity-summary"><div class="glass"><span>Trabajos registrados</span><strong>${tasks.length}</strong></div><div class="glass"><span>Cotizaciones registradas</span><strong>${fmt(tasks.reduce((n,j)=>n+(j.quotedCredits||0),0))}<small>cr</small></strong><p>No equivalen a cargos confirmados.</p></div><div class="glass"><span>Necesitan revisión</span><strong>${scoped.flatMap(p=>p.scenes.flatMap(s=>s.versions)).filter(v=>v.status==='review').length}<small>clips</small></strong></div></div><div class="activity-table glass"><div class="table-row table-head"><span>TRABAJO</span><span>ESTADO</span><span>COTIZACIÓN</span><span>FECHA</span></div>${tasks.map(j=>`<div class="table-row"><div><strong>${esc(j.label||'Nueva generación')}</strong><small>${esc(j.model)}</small></div><div>${badge(j.status)}${j.message?`<small>${esc(j.message)}</small>`:''}</div><span>${fmt(j.quotedCredits)} cr <small>Cargo no verificado</small></span><span>${date(j.createdAt)}</span></div>`).join('')}</div><h2 class="section-title">Últimas decisiones</h2><div class="event-list">${db.events.filter(e=>ids.has(e.pieceId)).slice(0,15).map(e=>`<div>${icon('check')}<span>${esc(e.text)}</span><small>${new Date(e.at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')}</div>`;}
function settings(){return `<div class="page-heading"><div><span class="eyebrow">TU ESPACIO, TUS HERRAMIENTAS</span><h1>Conexiones y estudio.</h1><p>Una base local. Herramientas conectadas cuando las necesitas.</p></div></div><div class="settings-grid">${themeSettings()}<section class="glass settings-card"><span class="connection-logo">H</span><h2>Higgsfield</h2><p>Generación de vídeo con Seedance. Cotización, envío y seguimiento desde las escenas.</p><div id="connection-status">${badge('review','Sesión por comprobar')}</div>${button('Comprobar conexión '+icon('arrow'),'check-connection','secondary')}</section><section class="glass settings-card"><span class="connection-logo eleven">Ⅱ</span><h2>ElevenLabs</h2><p>Dirección vocal por frase y locución. La conexión directa aún está pendiente.</p>${badge('draft','Pendiente de conectar')}<a href="https://elevenlabs.io/docs/eleven-agents/operate/hosted-mcp" target="_blank" rel="noopener noreferrer" class="text-btn">MCP oficial ${icon('arrow')}</a></section><section class="glass settings-card"><span class="connection-logo">↗</span><h2>Meta</h2><p>Publicación y rendimiento de las variantes. Previsto para una siguiente fase.</p>${badge('draft','No implementado')}</section><section class="glass settings-card"><span class="eyebrow">DIRECCIÓN VISUAL · EN EXPLORACIÓN</span><h2>Una base que puede cambiar.</h2><p>El color, la tipografía, los radios y las superficies están separados de la lógica del producto.</p><form id="brand-form"><label class="color-label">Acento<input type="color" name="accent" value="${esc(db.brand.accent)}"></label><button class="btn secondary" type="submit">Aplicar acento</button></form><button class="text-btn" data-act="references">Ver referencias guardadas ${icon('arrow')}</button></section><section class="glass settings-card"><span class="eyebrow">DATOS Y VERSIONES</span><h2>El trabajo permanece.</h2><p>Los cambios se guardan en este equipo y conservan versiones anteriores. Cerrar la ventana no elimina las piezas.</p><p>Studio 0.7.0 · Acceso local. La actualización automática y el acceso remoto todavía no están implementados.</p></section>${ecom.settingsCard()}</div>`;}
function empty(title,sub){return `<div class="empty-state">${icon('folder')}<h2>${esc(title)}</h2><p>${esc(sub)}</p></div>`;}
let modalReturnFocus=null;
function modal(title,content,wide=false){if(!$('#modal-root').children.length)modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2><button class="icon-btn" data-act="close-modal" aria-label="Cerrar">${icon('close')}</button></header>${content}</section></div>`;restoreDrafts();$('#modal-root input, #modal-root textarea, #modal-root button')?.focus();}
function closeModal(){const root=$('#modal-root'),overlay=root.firstElementChild,focus=modalReturnFocus;quote=null;const finish=()=>{if(root.firstElementChild===overlay){root.innerHTML='';if(focus?.isConnected)focus.focus({preventScroll:true});ecom?.refresh();}};if(overlay?.classList.contains('settings-backdrop')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){overlay.style.animation='none';const animation=overlay.animate([{opacity:1},{opacity:0}],{duration:180,easing:'ease-out',fill:'forwards'});return animation.finished.then(finish,finish);}else{finish();return Promise.resolve();}}
function lineFields(l){return{...l,text:$('#text-'+l.id)?.value??l.text,direction:$('#direction-'+l.id)?.value??l.direction,start:($(`[data-line="${l.id}"] [data-field="start"]`)?.value||'')===''?null:Number($(`[data-line="${l.id}"] [data-field="start"]`).value),end:($(`[data-line="${l.id}"] [data-field="end"]`)?.value||'')===''?null:Number($(`[data-line="${l.id}"] [data-field="end"]`).value)};}
function editScene(){const s=scene(),p=piece();modal('Dirigir la escena',`<form id="scene-form" class="form-stack"><label>Nombre<input name="title" value="${esc(s.title)}" required></label><label>Momento del guion<select name="lineId"><option value="">Sin frase asociada</option>${p.script.map(l=>`<option value="${l.id}" ${s.lineId===l.id?'selected':''}>${esc(l.text.slice(0,95))}</option>`).join('')}</select></label><label>Qué debe ocurrir<textarea name="intent" rows="5">${esc(s.intent)}</textarea></label><div class="two-fields"><label>Duración prevista (s)<input name="duration" type="number" min="0.1" max="60" step="0.1" value="${s.duration}"></label><label>Tratamiento de voz<select name="audioMode">${[['off','Voz en off'],['native','Voz nativa'],['silent','Sin voz'],['mixed','Off + diálogo']].map(([v,l])=>`<option value="${v}" ${s.audioMode===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label class="check-label"><input name="music" type="checkbox" ${s.music?'checked':''}> Música solicitada para esta escena</label><button class="btn primary" type="submit">Guardar dirección</button></form>`);}
function editRefs(){const s=scene();modal('Qué conservamos de cada referencia',`<form id="refs-form"><p class="muted">Elegir un recurso no aprueba todos sus elementos. Define el uso y confírmalo expresamente.</p><div class="refs-picker">${db.assets.filter(a=>a.kind==='image'&&a.category!=='inspiration'&&a.clientId===piece().clientId).map(a=>{const r=s.refs.find(r=>r.assetId===a.id);return `<div class="ref-pick"><img src="${media(a.id)}" alt=""><div><label class="check-label"><input type="checkbox" name="include" value="${a.id}" ${r?'checked':''}>${esc(a.name)}</label><select aria-label="Uso de ${esc(a.name)}" data-ref-role="${a.id}">${[['identity','Identidad y vestuario'],['product','Producto'],['palette','Color y luz'],['setting','Decorado']].map(([v,l])=>`<option value="${v}" ${r?.role===v?'selected':''}>${l}</option>`).join('')}</select><label class="check-label micro"><input type="checkbox" data-confirm="${a.id}" ${r?.confirmed?'checked':''}>Confirmo este uso</label></div></div>`;}).join('')}</div><button class="btn primary full" type="submit">Guardar referencias</button></form>`);}
function genPrompt(s){return `Create a ${s.duration}-second ${piece().format} video. Visual direction: ${piece().style||"Follow the scene intention and approved references; do not invent a style."}. Scene direction: ${s.intent}\n\nReferences: ${s.refs.map((r,i)=>`Image ${i+1}: ${asset(r.assetId)?.name}; use ONLY for ${({identity:'character identity and wardrobe',product:'product appearance',palette:'color palette and lighting',setting:'setting and spatial continuity'})[r.role]}`).join('. ')}. Reference images are not mandatory first frames.\n\nAudio: ${s.audioMode==='off'?'Environmental sound only. No speech or narration; voice-over will be added separately.':['native','mixed'].includes(s.audioMode)?'Native dialogue ONLY as explicitly directed above. Never speak text intended for the separate voice-over.':'No speech.'} ${s.music?'Original music as directed for the scene.':'No music.'} Preserve the intended emotion and physical action. No text overlays.`;}
function generate(){const s=scene();quote=null;modal('Preparar una generación',`<form id="quote-form" data-piece="${piece().id}" data-scene="${s.id}" class="form-stack"><div class="generation-summary"><span>Seedance 2.5</span><span>1080p</span><span>${esc(piece().format)}</span></div><p class="muted">Una única generación. Las referencias y el tratamiento de audio son los de esta escena.</p><label>Prompt para el modelo<textarea name="prompt" rows="9" required>${esc(genPrompt({...s,duration:Math.max(4,s.duration)}))}</textarea></label><label>Segundos a generar<input name="duration" type="number" min="4" max="30" step="1" value="${Math.max(4,s.duration)}"></label>${['off','mixed'].includes(s.audioMode)&&!piece().audioId?'<label class="check-label notice"><input name="pilotException" type="checkbox">Autorizo preparar esta prueba visual antes de disponer de la locución.</label>':''}<p class="micro">${s.refs.length} referencia(s) · ${s.refs.every(r=>r.confirmed)&&s.refs.length?'Usos confirmados':'Hay referencias pendientes de confirmar'}</p><button class="btn primary full" type="submit">Consultar coste</button></form><div id="quote-result"></div>`,true);}
async function upload(kind){modal(kind==='audio'?'Incorporar la locución':'Incorporar material',`<form id="upload-form" class="form-stack" data-kind="${kind}"><p class="muted">El original se conserva en este equipo. Hasta 150 MB por archivo.</p><label class="upload-zone">${icon('upload')}<span>Elige un archivo</span><input type="file" name="file" required accept="${kind==='audio'?'audio/*':kind==='video'?'video/*':kind==='reference'?'image/*':'image/*,video/*,audio/*'}"></label><button type="submit" class="btn primary">Guardar archivo</button></form>`);}
async function handle(a,e){const p=piece(),s=scene();switch(a){case'activity-period':{const period=['7','30','all'].includes(e.dataset.period)?e.dataset.period:'30';try{localStorage.setItem('studio-activity-period:'+ecom.brandId,period);}catch{}render();break;}case'braudi-preview':await closeModal();if(!await braudi.play())toast('Braudi está desactivado o esta ventana no está activa.');break;case'settings-popup':modal('Tu estudio',renderSettingsPopup({appearance:themeSettings(),icon,brandName:db.clients.find(c=>c.id===ecom.brandId)?.name||'Mi marca',esc,agentCard:ecom.settingsCard(),dev:ecom.dev,braudiEnabled:braudi.enabled}));$('#modal-root .modal-backdrop').classList.add('settings-backdrop');break;case'settings-advanced':closeModal();view='settings';render();break;case'review-drafts':{const pending=pendingDrafts();modal('Cambios sin guardar',`<p class="muted">La pieza está guardada. Estas correcciones siguen como borradores locales hasta que las guardes.</p><div class="draft-review-list">${pending.map(([key])=>`<button class="conversation-row" data-act="open-draft" data-key="${esc(key)}"><span>${esc(draftLabel(key))}</span>${icon('arrow')}</button>`).join('')||'<p>No hay cambios pendientes.</p>'}</div>`);break;}
 case'open-draft':{
  const key=e.dataset.key,[,pieceId,formId,sceneId,assetId]=key.split(':'),draft=memoryDrafts.get(key)||drafts.read(key);if(!draft||pieceId!==pid)break;
  const recover=()=>modal('Borrador conservado',`<p class="muted">Parte del contenido original ha cambiado. Conservamos el borrador completo para que puedas recuperarlo.</p><div class="recovered-draft">${draft.fields.filter(f=>f.key!=='_sourceScript'&&String(f.value??'').trim()).map(f=>`<p>${esc(f.value)}</p>`).join('')}</div>`);
  closeModal();
  if(formId==='script-form'){
   const saved=savedDraftFields(key);if(draft.fields.some(f=>f.key!=='_sourceScript'&&!saved?.some(s=>s.key===f.key))){recover();break;}
   tab='script';ecom.setGuideStep('script');render();
  }else if(formId==='brief-form')await handle('edit-brief',e);
  else if(sceneId&&piece().scenes.some(s=>s.id===sceneId)){
   sid=sceneId;vid=null;tab='scenes';ecom.setGuideStep('scenes');render();
   if(formId==='scene-form')editScene();
   else if(formId==='feedback-form'){
    if(scene().versions.some(v=>v.assetId===assetId))await handle('feedback',{dataset:{id:assetId}});else recover();
   }else if(formId==='note-form'){
    const input=$('#note-input'),details=input?.closest('details');if(details)details.open=true;
    if(input){input.focus({preventScroll:true});input.scrollIntoView({block:'nearest'});}else recover();
   }else recover();
  }else recover();
  break;
 }
 case'discard-draft':{const f=e.closest('form');f.reset();clearFormDraft(f);render();toast('Se ha recuperado la versión guardada.');break;}case'nav':view=e.dataset.view;closeModal();render();break;case'open-piece':pid=e.dataset.id;sid=piece().scenes[0]?.id;vid=null;view='piece';tab='scenes';chatScope=null;render();break;case'open-script':view='piece';tab='script';render();break;case'tab':tab=e.dataset.tab;render();break;case'scene':sid=e.dataset.id;chatScope=sid;vid=null;render();break;case'version':vid=e.dataset.id;render();requestAnimationFrame(()=>document.querySelector('.version-picker>summary')?.focus({preventScroll:true}));break;case'close-modal':closeModal();break;case'new-piece':modal('Una nueva pieza',`<form id="new-piece-form" class="form-stack"><label>Nombre<input name="title" placeholder="¿Cómo se llama esta idea?" required maxlength="180"></label><button type="submit" class="btn primary">Crear pieza ${icon('arrow')}</button></form>`);break;case'edit-brief':modal('La intención de la pieza',`<form id="brief-form" class="form-stack"><label>Título<input name="title" value="${esc(p.title)}" required></label><label>Qué queremos conseguir<textarea name="brief" rows="6">${esc(p.brief)}</textarea></label><button class="btn primary" type="submit">Guardar briefing</button></form>`);break;case'edit-scene':editScene();break;case'edit-refs':editRefs();break;case'generate':generate();break;case'add-scene':modal('Añadir una escena',`<form id="new-scene-form" class="form-stack"><label>Nombre<input name="title" placeholder="¿Qué ocurre en este plano?" required></label><button type="submit" class="btn primary">Añadir escena</button></form>`);break;case'approve':await act({type:'verdict',sceneId:s.id,assetId:e.dataset.id,status:'approved',select:true,feedback:s.versions.find(v=>v.assetId===e.dataset.id).feedback||'Aprobado desde Studio.'});render();toast('Versión aprobada y seleccionada para la entrega.');break;case'feedback':{const v=s.versions.find(v=>v.assetId===e.dataset.id);modal('Qué queremos corregir',`<form id="feedback-form" class="form-stack" data-asset="${v.assetId}"><label>Indicación concreta<textarea name="feedback" rows="5">${esc(v.feedback)}</textarea></label><label>Estado<select name="status"><option value="review">Por revisar</option><option value="rejected" ${v.status==='rejected'?'selected':''}>Descartado · conservar original</option></select></label><button class="btn primary" type="submit">Guardar corrección</button></form>`);break;}case'upload-audio':await upload('audio');break;case'upload-clip':await upload('video');break;case'ecom-upload-resource':document.querySelector('[data-v2="add-material"]')?.click();if(!document.querySelector('[data-v2="add-material"]')){view='brands';render();document.querySelector('[data-v2="add-material"]')?.click();}break;case'upload-resource':await upload('resource');break;case'upload-reference':await upload('reference');break;case'add-line':await act({type:'script',lines:[...p.script.map(lineFields),{id:crypto.randomUUID(),text:'',direction:'',start:null,end:null}]});if($('#script-form'))clearFormDraft($('#script-form'));render();break;case'filter':filter=e.dataset.filter;render();break;case'library-tab':referenceTab=e.dataset.ref==='true';render();break;case'design-study':closeModal();view='design-study';render();break;case'references':closeModal();view='library';referenceTab=true;render();break;case'asset-detail':{const a=asset(e.dataset.id);modal(a.name,`<div class="asset-detail">${a.kind==='image'?`<img src="${media(a.id)}" alt="${esc(a.name)}">`:a.kind==='video'?`<video controls src="${media(a.id)}"></video>`:a.kind==='audio'?`<audio controls src="${media(a.id)}"></audio>`:`<div class="waiting-card">${icon('file')}<span>${esc(a.name)}</span></div>`}<p>${a.category==='inspiration'?'Referencia de diseño. La preferencia concreta sigue abierta.':a.approved?'Identidad aprobada para reutilizar.':'El uso como referencia debe validarse por escena.'}</p><a class="btn secondary" href="${media(a.id)}" download="${esc(a.name)}">${icon('download')} Descargar original</a></div>`);break;}case'add-reference':modal('Guardar una referencia',`${button(icon('upload')+' Guardar una imagen original','upload-reference','secondary full')}<p class="micro">O conserva un enlace:</p><form id="reference-form" class="form-stack"><label>Título<input name="title" required></label><label>Enlace original<input name="url" type="url" placeholder="https://" required></label><label>Qué quieres conservar o explorar<textarea name="note" rows="4" placeholder="Puede quedar abierto. No hace falta decidir qué te gusta todavía."></textarea></label><button class="btn primary" type="submit">Guardar referencia</button></form>`);break;case'check-connection':e.disabled=true;e.textContent='Comprobando…';{const d=await api('/api/connections/check',{method:'POST'});$('#connection-status').innerHTML=badge(d.higgsfield==='connected'?'approved':'review',d.higgsfield==='connected'?'Conexión verificada':'No verificada');if(d.message)toast(d.message);e.disabled=false;e.textContent='Comprobar conexión';}break;case'reconcile':await api('/api/reconcile',{method:'POST'});toast('Consultando los trabajos pendientes; no se reenvían.');break;case'export':{const readiness=deliveryReadiness(p,db.assets),pending=[...readiness.missing,...readiness.warnings];modal('Preparar el paquete de edición',`<p class="muted">Incluye los clips aprobados y seleccionados, referencias, guion, dirección y tiempos. Conserva los originales.</p><div class="export-summary"><strong>${readiness.selected} ${p.kind==='video'?'clips':'imágenes'} seleccionados</strong><span>${readiness.readyForEditing?'Material preparado para edición':'Entrega parcial: quedan puntos por resolver'}</span></div>${pending.length?`<ul>${pending.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}<p class="micro">Los pendientes también quedan registrados en el briefing. El paquete no es un montaje final.</p><a href="/api/export?pieceId=${encodeURIComponent(pid)}" class="btn primary full" download>${icon('download')} ${pending.length?'Descargar entrega parcial':'Descargar paquete .zip'}</a>`);break;}case'timeline-edit':{const sc=p.scenes.find(x=>x.id===e.dataset.id),id=sc.timeline?.assetId||sc.selectedId||sc.versions.at(-1).assetId,aa=asset(id);modal('Encajar el plano',`<form id="timeline-form" data-scene="${sc.id}" class="form-stack"><label>Versión<select name="assetId">${sc.versions.map(v=>`<option value="${v.assetId}" ${v.assetId===id?'selected':''}>${esc(v.label)} · ${status(v.status)}</option>`).join('')}</select></label><label>Empieza en el anuncio (s)<input type="number" name="start" min="0" step="0.01" value="${sc.timeline?.start||0}"></label><div class="two-fields"><label>Usar el archivo desde (s)<input type="number" name="in" min="0" step="0.01" value="${sc.timeline?.in||0}"></label><label>Hasta (s)<input type="number" name="out" min="0" step="0.01" value="${sc.timeline?.out||aa.duration}"></label></div><label class="check-label"><input name="muted" type="checkbox" ${sc.timeline?.muted?'checked':''}>Silenciar el audio nativo de este clip</label><button type="submit" class="btn primary">Guardar tiempos</button></form>`);break;}case'add-pick':modal('Una referencia con criterio.',`<form id="pick-form" class="form-stack"><label>Título<input name="title" required maxlength="200"></label><label>Referencia<input name="url" type="url" required></label><label>Por qué la elegimos<textarea name="note" rows="4" required maxlength="6000"></textarea></label><label>Selección de<input name="author" value="BRAUD" maxlength="100"></label><p class="micro">Se guarda en este estudio. La sincronización con el portal todavía está pendiente.</p><button class="btn primary" type="submit">Guardar selección</button></form>`);break;case'reuse-clip':{const clips=db.assets.filter(a=>a.kind==='video'&&a.clientId===p.clientId&&a.category!=='inspiration'&&!s.versions.some(v=>v.assetId===a.id));modal('Un clip, otra posibilidad.',`<p class="muted">Conservamos el original y lo incorporamos a esta escena para revisarlo. Sin generar de nuevo.</p><div class="reuse-list">${clips.map(a=>`<button class="conversation-row" data-act="reuse-select" data-id="${a.id}"><div><strong>${esc(a.name)}</strong><small>${fmt(a.duration)} s · ${esc(db.pieces.find(x=>x.id===a.pieceId)?.title||'Biblioteca')}</small></div>${icon('plus')}</button>`).join('')||'<p>No hay otros clips disponibles en esta marca.</p>'}</div>`);break;}case'reuse-select':await act({type:'reuse-clip',sceneId:s.id,assetId:e.dataset.id});vid=e.dataset.id;closeModal();render();toast('Clip incorporado para revisar. El original se conserva.');break;case'expand-preview':{const selected=s.versions.find(v=>v.assetId===vid)||s.versions.find(v=>v.assetId===s.selectedId)||s.versions.at(-1),a=selected&&asset(selected.assetId);if(a)modal(s.title,`<div class="expanded-preview"><video controls playsinline src="${media(a.id)}"></video></div>`,true);break;}case'play-assembly':window.studioPreview?.toggle();break;case'submit-generation':if(!quote)return;e.disabled=true;{const d=await api('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quoteId:quote.id})});db=d.state;closeModal();render();toast('Generación enviada. Puedes seguir trabajando; el resultado aparecerá en la escena.');}break;}}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-act]');if(!target)return;try{await handle(target.dataset.act,target);}catch(err){toast(err.message);target.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-braudi-enabled]'))void braudi.setEnabled(e.target.checked);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root').children.length){const els=$$('#modal-root button:not(:disabled),#modal-root input:not(:disabled),#modal-root textarea:not(:disabled),#modal-root select:not(:disabled),#modal-root a[href]');if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f)),submit=f.querySelector('[type="submit"]');if(busy)return;busy=true;if(submit)submit.disabled=true;try{switch(f.id){case'new-idea':{const p=await act({type:'create-piece',title:values.idea.slice(0,100)});pid=p.id;await act({type:'piece',title:p.title,brief:values.idea});sid=null;view='piece';tab='script';render();toast('Idea guardada. Desarrolla el guion y la dirección.');break;}case'new-piece-form':{const p=await act({type:'create-piece',title:values.title});pid=p.id;sid=null;view='piece';tab='script';closeModal();render();break;}case'brief-form':await act({type:'piece',...values});clearFormDraft(f);closeModal();render();break;case'scene-form':await act({type:'scene',sceneId:scene().id,...values,music:f.elements.music.checked});clearFormDraft(f);closeModal();render();break;case'new-scene-form':await act({type:'scene-add',title:values.title});sid=piece().scenes.at(-1).id;tab='scenes';closeModal();render();break;case'script-form':{if(values._sourceScript!==JSON.stringify(piece().script))throw Error('El agente ha actualizado este guion. Tu borrador sigue guardado; revisa los cambios antes de sustituirlo.');const lines=piece().script.map(lineFields);if(lines.some(l=>l.start!==null&&l.end!==null&&l.end<=l.start))throw Error('La salida de una frase debe ser posterior a su entrada.');await act({type:'script',lines});clearFormDraft(f);render();toast('Guion e interpretación guardados.');break;}case'note-form':await act({type:'note',sceneId:scene().id,text:values.note});clearFormDraft(f);render();toast('Indicación guardada literalmente.');break;case'refs-form':{const refs=[...f.querySelectorAll('[name="include"]:checked')].map(el=>({assetId:el.value,role:f.querySelector(`[data-ref-role="${el.value}"]`).value,confirmed:f.querySelector(`[data-confirm="${el.value}"]`).checked}));await act({type:'refs',sceneId:scene().id,refs});closeModal();render();break;}case'feedback-form':await act({type:'verdict',sceneId:scene().id,assetId:f.dataset.asset,status:values.status,feedback:values.feedback});clearFormDraft(f);closeModal();render();break;case'brand-form':await act({type:'brand',accent:values.accent});render();toast('Acento actualizado.');break;case'pick-form':await act({type:'founder-pick-add',...values});closeModal();render();toast('Selección guardada.');break;case'reference-form':await act({type:'reference-add',...values});closeModal();render();break;case'timeline-form':await act({type:'timeline',sceneId:f.dataset.scene,...values,muted:f.elements.muted.checked});closeModal();render();break;case'upload-form':{const file=f.elements.file.files[0];if(!file)throw Error('Elige un archivo.');const r=await api((view==='library'&&f.dataset.kind==='resource'?'/api/material/upload?clientId='+studio.client().id:`/api/upload?pieceId=${pid}${f.dataset.kind==='video'?'&sceneId='+scene().id:f.dataset.kind==='reference'?'&reference=true':''}`),{method:'POST',headers:{'X-File-Name':encodeURIComponent(file.name)},body:file});db=r.state;closeModal();render();toast('Original incorporado y guardado en local.');break;}case'quote-form':{if(submit)submit.textContent='Consultando el coste real…';const r=await api('/api/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pieceId:f.dataset.piece,sceneId:f.dataset.scene,prompt:values.prompt.replace(/^Create a [0-9.]+-second/,`Create a ${Number(values.duration)}-second`),duration:Number(values.duration),pilotException:!!values.pilotException})});db=r.state;quote=r.quote;$$('#quote-form input, #quote-form textarea, #quote-form button').forEach(x=>x.disabled=true);$('#quote-result').innerHTML=`<div class="quote-card"><span>COTIZACIÓN DEL PROVEEDOR</span><strong>${fmt(quote.credits)} <small>créditos</small></strong><p>Una generación. No incluye reintentos. Válida durante 10 minutos.</p>${button('Autorizar y generar '+icon('arrow'),'submit-generation','primary full')}</div>`;break;}}}catch(err){toast(err.message);}finally{busy=false;if(submit&&f.id!=='quote-form')submit.disabled=false;if(submit&&f.id==='quote-form'&&!quote){submit.disabled=false;submit.textContent='Consultar coste';}}});
function initPreview(){const p=piece(),video=$('#assembly-video'),audio=$('#master-audio'),seek=$('#assembly-seek');if(!video)return;let playing=false,t=0,last=performance.now(),raf,cur=null;const clips=p.scenes.filter(s=>s.versions.length).map(s=>({s,a:asset(s.timeline?.assetId||s.selectedId||s.versions.at(-1).assetId)}));function draw(){const c=clips.find(({s,a})=>t>=(s.timeline?.start||0)&&t<(s.timeline?.start||0)+(s.timeline?.out??a.duration)-(s.timeline?.in||0));$('#assembly-empty').style.display=c?'none':'grid';video.style.opacity=c?'1':'0';if(c){const pos=t-(c.s.timeline?.start||0)+(c.s.timeline?.in||0);if(cur!==c.a.id){cur=c.a.id;video.src=media(cur);video.currentTime=pos;}else if(Math.abs(video.currentTime-pos)>.3)video.currentTime=pos;video.muted=!!c.s.timeline?.muted;if(playing&&video.paused)video.play().catch(()=>{});if(!playing)video.pause();}else video.pause();seek.value=t;$('#assembly-time').textContent=`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')} / ${fmt(seek.max)} s`;}
function tick(now){if(!playing)return;t=audio&&!audio.paused?audio.currentTime:t+(now-last)/1000;last=now;if(t>=Number(seek.max)){t=0;playing=false;audio?.pause();if(audio)audio.currentTime=0;video.pause();$('[data-act="play-assembly"]').innerHTML=icon('play')+' Reproducir';}draw();if(playing)raf=requestAnimationFrame(tick);}
window.studioPreview={toggle(){playing=!playing;last=performance.now();$('[data-act="play-assembly"]').innerHTML=playing?'Pausar':icon('play')+' Reproducir';if(playing){if(audio){audio.currentTime=t;audio.play().catch(()=>toast('Pulsa reproducir para activar el audio.'));}raf=requestAnimationFrame(tick);}else{audio?.pause();video.pause();cancelAnimationFrame(raf);}draw();}};seek.addEventListener('input',()=>{t=Number(seek.value);if(audio)audio.currentTime=t;draw();});previewStop=()=>{playing=false;cancelAnimationFrame(raf);audio?.pause();video.pause();previewStop=null;};draw();}
// The workspace keeps one geometry across scenes, tabs and chat updates.
let layoutFrame;
function layoutLimits(){
 const available=$('.workspace-shell')?.clientWidth||innerWidth;
 const scenes=!!$('#piece-board .scene-workspace');
 const editorMin=scenes?(innerWidth>=1500?956:innerWidth>1220?786:innerWidth>1050?663:innerWidth>900?529:250):Math.min(480,available-300);
 const gap=innerWidth>1050?28:20;
 return {min:280,max:Math.max(280,Math.min(480,available-editorMin-gap))};
}
function layoutWidth(){try{return Number(localStorage.getItem('studio-agent-width:'+ecom.brandId))||330;}catch{return 330;}}
function setLayoutWidth(value,save=false){const {min,max}=layoutLimits(),width=Math.round(Math.max(min,Math.min(max,value)));document.documentElement.style.setProperty('--agent-width',width+'px');const grip=$('[data-resize="agent"]');if(grip){grip.setAttribute('aria-valuemin',min);grip.setAttribute('aria-valuemax',max);grip.setAttribute('aria-valuenow',width);grip.setAttribute('aria-valuetext',width+' píxeles');grip.setAttribute('aria-label','Anchura del agente');}if(save)try{localStorage.setItem('studio-agent-width:'+ecom.brandId,String(width));}catch{}return width;}
let layoutObserver;
// Read layout coordinates, not the temporary transforms used by entry animations.
function layoutTop(node){let top=0;for(let el=node;el;el=el.offsetParent)top+=el.offsetTop;return top;}
function fitDock(){
 const shell=$('.workspace-shell'),board=$('#piece-board'),overview=$('.workspace-overview');if(!shell||!board)return;
 const canvas=board.querySelector('.scene-canvas'),raised=innerWidth>700&&$('.workspace-layout')?.dataset.agentPosition==='title';
 const shellTop=layoutTop(shell),canvasOffset=canvas?Math.max(0,layoutTop(canvas)-shellTop):0;
 const title=overview?.querySelector('.guide-heading h1')||overview;
 const offset=raised?layoutTop(title)-shellTop:canvasOffset;
 // The chosen heading owns the upper edge; the editor owns the lower edge.
 // Fit the composer into the *remaining* viewport, not an entire screen below
 // that heading. The same bottom is retained when the heading is raised.
 const top=shellTop+offset,bottom=canvas&&innerWidth>900?layoutTop(canvas)+canvas.offsetHeight:shellTop+board.offsetHeight;
 const height=dockViewportHeight({top,bottom,viewportHeight:innerHeight,scrollTop:window.scrollY});
 const history=shell.querySelector('.agent-history'),reading=history?{top:history.scrollTop,left:history.scrollLeft,following:history._followTail!==false}:null;
 if(canvas)shell.style.setProperty('--scene-height',canvas.offsetHeight+'px');
 else shell.style.removeProperty('--scene-height');
 shell.style.setProperty('--dock-offset',offset+'px');
 shell.style.setProperty('--dock-height',height+'px');
 // Resizing the history must not change which response the person is reading.
 if(reading){history.scrollTop=reading.following?Math.max(0,history.scrollHeight-history.clientHeight):reading.top;history.scrollLeft=reading.left;history._lastReadTop=history.scrollTop;history._followTail=reading.following;}
}
function applyLayout(){cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{
 setLayoutWidth(layoutWidth());fitDock();
 layoutObserver?.disconnect();
 layoutObserver=new ResizeObserver(fitDock);
 for(const node of [$('#piece-board'),$('.workspace-overview'),$('#piece-board .scene-canvas')])if(node)layoutObserver.observe(node);
});}
document.addEventListener('toggle',e=>{if(e.target.matches?.('.review-feedback'))applyLayout();},true);
document.addEventListener('pointerdown',e=>{const grip=e.target.closest('[data-resize="agent"]');if(!grip||e.button!==0||innerWidth<900)return;e.preventDefault();const startX=e.clientX,startWidth=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--agent-width'))||330;grip.setPointerCapture(e.pointerId);document.body.classList.add('resizing-panels');let width=startWidth;const move=event=>{width=setLayoutWidth(startWidth+startX-event.clientX);};const done=()=>{setLayoutWidth(width,true);document.body.classList.remove('resizing-panels');grip.removeEventListener('pointermove',move);grip.removeEventListener('pointerup',done);grip.removeEventListener('pointercancel',done);grip.removeEventListener('lostpointercapture',done);applyLayout();};grip.addEventListener('pointermove',move);grip.addEventListener('pointerup',done);grip.addEventListener('pointercancel',done);grip.addEventListener('lostpointercapture',done);});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-resize="agent"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const limits=layoutLimits(),current=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--agent-width'))||330;setLayoutWidth(e.key==='Home'?limits.min:e.key==='End'?limits.max:current+(e.key==='ArrowLeft'?20:-20),true);applyLayout();});
window.addEventListener('resize',applyLayout);
let dockScrollFrame=0;
window.addEventListener('scroll',()=>{if(dockScrollFrame)return;dockScrollFrame=requestAnimationFrame(()=>{dockScrollFrame=0;if(innerWidth>700)fitDock();});},{passive:true});
function refreshBoard(){const board=$('#piece-board');if(!board)return;const dirty=board.querySelector('form .draft-notice:not([hidden])'),focused=board.contains(document.activeElement)&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);if(dirty||focused||[...board.querySelectorAll('audio')].some(a=>!a.paused)||(tab==='assembly'&&$('#assembly-video')&&!$('#assembly-video').paused)){let notice=$('#board-pending');if(!notice){notice=document.createElement('button');notice.id='board-pending';notice.className='board-pending';notice.dataset.ecom='board-update';notice.textContent='La pieza tiene cambios · actualizar vista';board.prepend(notice);}return;}captureFlow();const video=board.querySelector('.preview-stage video'),oldTop=board.scrollTop,positions=['.direction-panel','.scene-rail'].map(selector=>({selector,top:board.querySelector(selector)?.scrollTop||0}));const layout=ecom.board(true);board.innerHTML=layout.content;const overview=$('.workspace-overview');if(overview)overview.innerHTML=layout.overview;const fresh=board.querySelector('.preview-stage video');if(video&&fresh&&video.getAttribute('src')===fresh.getAttribute('src'))fresh.replaceWith(video);board.scrollTop=oldTop;for(const pos of positions){const el=board.querySelector(pos.selector);if(el)el.scrollTop=pos.top;}if(tab==='assembly'){if(previewStop)previewStop();initPreview();}restoreDrafts();applyLayout();settleFlow({fitLayout:fitDock});}
