let stateLoading=false,streamConnected=false,refreshAgain=false;
async function pullState(){if(stateLoading){refreshAgain=true;return;}stateLoading=true;try{db=await api('/api/state');if(!$('#modal-root').children.length){if(!ecom.refresh()&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))render();}}catch{}finally{stateLoading=false;if(refreshAgain){refreshAgain=false;void pullState();}}}
const stream=new EventSource('/api/agent/events?clientId='+encodeURIComponent(ecom.brandId));
stream.onopen=()=>{streamConnected=true;};stream.onerror=()=>{streamConnected=false;};
stream.onmessage=e=>{try{const v=JSON.parse(e.data);if(v.revision!==db.revision){void pullState();return;}db.conversations=[...db.conversations.filter(c=>c.clientId!==ecom.brandId),...v.conversations];db.liveRevision=v.liveRevision;if(!$('#modal-root').children.length)ecom.refresh();}catch{}};
